def trans(g):
 coords=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8]
 r0=min(r for r,c in coords);r1=max(r for r,c in coords);c0=min(c for r,c in coords);c1=max(c for r,c in coords)
 out=[]
 for r in range(r0,r1+1):
  row=[]
  for c in range(c0,c1+1):
   sr,sc=31-r,31-c
   if not (0<=sr<len(g) and 0<=sc<len(g[0])):
    sc=29-c
    if not (0<=sc<len(g[0])): sc=max(0,min(len(g[0])-1,sc))
   val=g[sr][sc]
   if val==8:
    # fallback use same-row mirrored to right edge (nearest valid mirror)
    sr0=r
    sc0=29-c
    if 0<=sc0<len(g[0]) and g[sr0][sc0]!=8: val=g[sr0][sc0]
   row.append(val)
  out.append(row)
 return out
